inputs = ['bbyujy', 'xacuug', 'izv', 'vjhwd', 'kjwh']
outputs = ['bbyujy', 'xbywcuug', 'icvgcvv', 'vjhwd', 'kjwh']

# Analyze the differences
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"Example {i}: '{inp}' → '{outp}'")
        print(f"  Length: {len(inp)} → {len(outp)}")
        # Find differences
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' → '{outp[j]}'")
        if len(inp) != len(outp):
            print(f"  Length difference: {len(outp) - len(inp)} characters added")
        print()

